UPDATE mt_shop
SET historical_order_backfill_status = #{processingStatus},
    historical_order_backfill_at = #{backfillAt},
    update_time = #{updateTime}
WHERE id = #{id}
  AND historical_order_backfill_status = #{expectedStatus}

UPDATE mt_shop
SET historical_order_backfill_status = #{processingStatus},
    historical_order_backfill_at = #{backfillAt},
    update_time = #{updateTime}
WHERE id = #{id}
  AND historical_order_backfill_status IN (#{initStatus}, #{failedStatus})

